function buildPassages(): CorpusPassage[] {
  const passages: CorpusPassage[] = [
    {
      key: `${PREFIX}.title`,
      divisionKind: "section",
      label: "Title of the book",
      reference: `Budge, The Egyptian Heaven and Hell, vol. I, ${AMDUAT_TITLE.pages}`,
      sourceKey: "budge-heaven-hell",
      summary: "The book's own title, listing what it teaches: the souls, gods, doors, roads and hours of the hidden palace at the western horizon.",
      verificationStatus: "unverified",
      notes: "Not counted as an hour.",
      layers: [budgeLayer(AMDUAT_TITLE, `vol. I, ${AMDUAT_TITLE.pages}`)],
    },
  ];
  AMDUAT_HOURS.forEach((hour, i) => {
    const meta = HOURS[hour.hour];
    const hourKey = `${PREFIX}.${hour.hour}`;
    passages.push({
      key: hourKey,
      divisionKind: "hour",
      label: meta.label,
      reference: `Hour ${hour.hour}; Budge, The Egyptian Heaven and Hell, vol. I, chap. ${hour.chapter}`,
      sourceKey: "budge-heaven-hell",
      summary: meta.summary,
      notes: [`Budge's heading: '${hour.heading}'`, meta.notes].filter(Boolean).join(" "),
      verificationStatus: "unverified",
      layers: cited(hour.hour),
      witnesses: [
        { manuscriptKey: "kv34", locus: `Hour ${hour.hour}` },
        { manuscriptKey: "kv35", locus: `Hour ${hour.hour}` },
      ],
      dates: i === 0 ? DATES : undefined,
      themes: meta.themes?.map(([themeKey, note]) => ({ themeKey, note })),
      images: imagesFor(AMDUAT_IMAGES, hourKey),
    });
    for (const section of hour.sections) {
      const key = `${hourKey}.${section.key}`;
      const where = `vol. I, chap. ${hour.chapter}, ${section.pages}`;
      passages.push({
        key,
        parentKey: hourKey,
        divisionKind: sectionDivisionKind(section.key),
        label: `Hour ${hour.hour}: ${section.label.charAt(0).toLowerCase()}${section.label.slice(1)}`,
        reference: `Budge, The Egyptian Heaven and Hell, ${where}`,
        sourceKey: "budge-heaven-hell",
        verificationStatus: "unverified",
        layers: [budgeLayer(section, where)],
        images: imagesFor(AMDUAT_IMAGES, key),
      });
    }
  });

  const shortKey = `${PREFIX}.short`;
  passages.push({
    key: shortKey,
    divisionKind: "version",
    label: "The Short Form (the 'Summary' of the Amduat)",
    reference: "Budge, The Egyptian Heaven and Hell, vol. II, pp. 1–39",
    sourceKey: "budge-heaven-hell",
    summary: "A condensed version of the book, hour by hour, giving the names, measures and duties of each hour without the pictures.",
    notes:
      "Budge names as its authorities the copies Jéquier used for his edition (1894) — the Berlin, Leiden, Louvre and Turin papyri and the tomb of Seti I — and calls Leiden Papyrus T 71 the most valuable (vol. III, p. 84). Its hours are not counted as units of the work. The page ranges of the individual hours could not be recovered reliably from the e-text and are not given.",
    verificationStatus: "unverified",
    layers: [],
  });
  for (const hour of SHORT_AMDUAT) {
    const key = `${shortKey}.${hour.hour}`;
    passages.push({
      key,
      parentKey: shortKey,
      divisionKind: "section",
      label: `Short Form, hour ${hour.hour}`,
      reference: `Budge, The Egyptian Heaven and Hell, vol. II, The Short Form of the Book Am-Tuat, '${hour.heading.replace(/\.$/, "")}'`,
      sourceKey: "budge-heaven-hell",
      notes: SHORT_NOTES[hour.hour],
      verificationStatus: "unverified",
      layers: [budgeLayer(hour, `vol. II, Short Form, ${hour.heading.replace(/\.$/, "").toLowerCase()}`)],
      images: imagesFor(AMDUAT_IMAGES, key),
    });
  }
  return passages;
}

